161	/** Save the settings the input sets: each dated one recorded from its from-date (not given: the sheet's today),
162	 *  keeping the values already recorded (one from that same date is replaced); the policy date and the period
163	 *  numbering from and the grace days and the permission matrix as
164	 *  they are. */
165	public class SaveSettings {
166	    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
167	            Out<Settings> settings) {
168	        String id = sheetId.trim();
169	        LocalDate today = repository.today(id);
170	        if (input.setsClerkLimit()) {
171	            repository.setDated(id, "clerk-limit", text(input.clerkLimit()), from(input, "clerk-limit", today));
172	        }
173	        if (input.floor() != null) {
174	            repository.setDated(id, "floor", text(input.floor()), from(input, "floor", today));
175	        }
176	        if (input.terms() != null) {
177	            repository.setDated(id, "terms", String.valueOf(input.terms()), from(input, "terms", today));
178	        }
179	        input.gradeTerms().forEach((grade, days) -> repository.setDated(id, "terms-" + grade,
180	                days != null ? String.valueOf(days) : null, from(input, "terms-" + grade, today)));
181	        if (input.latePct() != null) {
182	            repository.setDated(id, "late-pct", text(input.latePct()), from(input, "late-pct", today));
183	        }
184	        if (input.setsPolicyDate()) {
185	            repository.setPolicyDate(id, input.policyDate());
186	        }
187	        if (input.setsPeriodNumberingFrom()) {
188	            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
189	        }
190	        if (input.setsCap()) {
191	            repository.setDated(id, "cap", text(input.cap()), from(input, "cap", today));
192	        }
193	        if (input.setsProofThreshold()) {
194	            repository.setDated(id, "proof-threshold", text(input.proofThreshold()), from(input, "proof-threshold", today));
195	        }
196	        if (input.setsNoteThreshold()) {
197	            repository.setDated(id, "note-threshold", text(input.noteThreshold()), from(input, "note-threshold", today));
198	        }
199	        if (input.setsGraceDays()) {
200	            repository.setGraceDays(id, input.graceDays());
201	        }
202	        input.perms().forEach((action, roles) -> repository.setPermission(id, action, roles));
203	        settings.set(repository.of(id));
204	    }
205	
206	    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
207	        LocalDate from = input.from().get(key);
208	        return from != null ? from : today != null ? today : LocalDate.of(1, 1, 1);
209	    }
210	
211	    private static String text(BigDecimal value) {
212	        return value != null ? value.toPlainString() : null;
213	    }
