609	 *  today) or a date yyyy-mm-dd, and permission entries (when given) only for open, settle, void, reassign, close or
610	 *  reopen, each blank (the standing rule) or a comma separated list of clerk and steward, and grace days (when given) blank (off) or a whole number of days, and a note threshold (when given) blank (none) or an amount 0.00 or more with up to two decimals. */
611	public class ValidateSettings {
612	    /** The grades that may have terms of their own. */
613	    static final List<String> GRADES = List.of("A", "B", "C");
614	
615	    private static final String PERCENT = "\\d{1,3}(\\.\\d{1,2})?";
616	    private static final String AMOUNT = "\\d{1,12}(\\.\\d{1,2})?";
617	
618	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingException {
619	        if (request == null || request.user() == null || request.user().isBlank()) {
620	            throw new InvalidSettingException("Sign in before changing settings.");
621	        }
622	        String limit = request.clerkLimit() == null ? null : request.clerkLimit().trim();
623	        if (limit != null && !limit.isEmpty() && !limit.matches(AMOUNT)) {
624	            throw new InvalidSettingException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank for no limit.");
625	        }
626	        String floor = request.floor() == null ? null : request.floor().trim();
627	        if (floor != null && !floor.matches(AMOUNT)) {
628	            throw new InvalidSettingException("The floor must be an amount, 0.00 or more, with up to two decimals.");
629	        }
630	        String terms = request.terms() == null ? null : request.terms().trim();
631	        if (terms != null && !terms.matches("\\d{1,4}")) {
632	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
633	        }
634	        String latePct = request.latePct() == null ? null : request.latePct().trim();
635	        if (latePct != null && !latePct.matches(PERCENT)) {
636	            throw new InvalidSettingException("The late percent must be a percent, 0.00 or more, with up to two decimals.");
637	        }
638	        String policy = request.policyDate() == null ? null : request.policyDate().trim();
639	        LocalDate policyDate = null;
640	        if (policy != null && !policy.isEmpty()) {
641	            try {
642	                policyDate = LocalDate.parse(policy);
643	            } catch (DateTimeParseException e) {
644	                throw new InvalidSettingException("The policy date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
645	            }
646	        }
647	        String numbering = request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
648	        LocalDate numberingFrom = null;
649	        if (numbering != null && !numbering.isEmpty()) {
650	            try {
651	                numberingFrom = LocalDate.parse(numbering);
652	            } catch (DateTimeParseException e) {
653	                throw new InvalidSettingException("The period numbering from must be a date, yyyy-mm-dd, or blank for off.");
654	            }
655	        }
656	        String cap = request.cap() == null ? null : request.cap().trim();
657	        if (cap != null && !cap.isEmpty() && !cap.matches(AMOUNT)) {
658	            throw new InvalidSettingException("The cap must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
659	        }
660	        String threshold = request.proofThreshold() == null ? null : request.proofThreshold().trim();
661	        if (threshold != null && !threshold.isEmpty() && !threshold.matches(AMOUNT)) {
662	            throw new InvalidSettingException("The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
663	        }
664	        String noteThreshold = request.noteThreshold() == null ? null : request.noteThreshold().trim();
665	        if (noteThreshold != null && !noteThreshold.isEmpty() && !noteThreshold.matches(AMOUNT)) {
666	            throw new InvalidSettingException("The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank for none.");
667	        }
668	        String grace = request.graceDays() == null ? null : request.graceDays().trim();
669	        if (grace != null && !grace.isEmpty() && !grace.matches("\\d{1,4}")) {
670	            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank for off.");
671	        }
672	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
673	        if (request.gradeTerms() != null) {
674	            for (String grade : request.gradeTerms().keySet()) {
675	                if (!GRADES.contains(grade)) {
676	                    throw new InvalidSettingException("Terms may be set only for grade A, B or C.");
677	                }
678	            }
679	            for (String grade : GRADES) {
680	                if (!request.gradeTerms().containsKey(grade)) {
681	                    continue;
682	                }
683	                String days = request.gradeTerms().get(grade) == null ? "" : request.gradeTerms().get(grade).trim();
684	                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
685	                    throw new InvalidSettingException("The terms of grade " + grade
686	                            + " must be a whole number of days, 0 or more, or blank for the sheet's terms.");
687	                }
688	                gradeTerms.put(grade, days.isEmpty() ? null : Integer.valueOf(days));
689	            }
690	        }
691	        Map<String, String> perms = new LinkedHashMap<>();
692	        if (request.perms() != null) {
693	            for (String action : request.perms().keySet()) {
694	                if (!Permissions.ACTIONS.contains(action)) {
695	                    throw new InvalidSettingException("Permissions may be set only for open, settle, void, reassign, close or reopen.");
696	                }
697	            }
698	            for (String action : Permissions.ACTIONS) {
699	                if (!request.perms().containsKey(action)) {
700	                    continue;
701	                }
702	                String entry = request.perms().get(action) == null ? "" : request.perms().get(action).trim();
703	                List<String> roles = new ArrayList<>();
704	                if (!entry.isEmpty()) {
705	                    for (String role : entry.split(",", -1)) {
706	                        String r = role.trim();
707	                        if (!r.equals(Role.CLERK) && !r.equals(Role.STEWARD)) {
708	                            throw new InvalidSettingException("The roles allowed to " + action
709	                                    + " must be a comma separated list of clerk and steward, or blank for the standing rule.");
710	                        }
711	                        if (!roles.contains(r)) {
712	                            roles.add(r);
713	                        }
714	                    }
715	                }
716	                perms.put(action, String.join(",", roles));
717	            }
718	        }
719	        Map<String, LocalDate> from = new LinkedHashMap<>();
720	        if (request.from() != null) {
721	            for (var e : request.from().entrySet()) {
722	                if (!SettingHistory.KEYS.contains(e.getKey())) {
723	                    throw new InvalidSettingException("Only a setting that carries a figure takes a from-date.");
724	                }
725	                String date = e.getValue() == null ? "" : e.getValue().trim();
726	                if (date.isEmpty()) {
727	                    continue;
728	                }
729	                try {
730	                    from.put(e.getKey(), LocalDate.parse(date));
731	                } catch (DateTimeParseException ex) {
732	                    throw new InvalidSettingException("The from-date must be a date, yyyy-mm-dd, or blank for the sheet's today.");
733	                }
734	            }
735	        }
736	        body.set(new SettingsInput(request.user().trim(), limit != null,
737	                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
738	                floor == null ? null : new BigDecimal(floor).setScale(2),
739	                terms == null ? null : Integer.valueOf(terms),
740	                latePct == null ? null : new BigDecimal(latePct).setScale(2),
741	                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
742	                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from,
743	                threshold != null, threshold == null || threshold.isEmpty() ? null : new BigDecimal(threshold).setScale(2),
744	                perms, grace != null, grace == null || grace.isEmpty() ? null : Integer.valueOf(grace),
745	                noteThreshold != null,
746	                noteThreshold == null || noteThreshold.isEmpty() ? null : new BigDecimal(noteThreshold).setScale(2)));
747	    }
748	}
749	-- The sheet's period numbering from (null: off). While it is a date and the sheet's today is on or after it, a
750	-- claim opened is numbered within its period: <period name>-<n>, counting from 1 in each period; a claim in no
751	-- period is numbered X-<n> in its own sequence. A claim's number (and the number a correction names) is now text:
752	-- a sheet-wide number is kept as its digits.
753	ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
754	ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
755	ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
756	-- The last number given in each period's sequence on a sheet ('X' for the claims in no period), by the
757	-- period's name as compared on the sheet (lower case, trimmed).
758	CREATE TABLE period_number (
759	    sheet_id    VARCHAR(100) NOT NULL REFERENCES sheet(id),
760	    seq_key     VARCHAR(220) NOT NULL,
761	    last_number INT          NOT NULL,
762	    PRIMARY KEY (sheet_id, seq_key)
763	);
764	-- The sheet's rounding policy date (null: the sheet's today): a claim dated before it rounds half up, one dated on or
765	-- after it half to even. A correction rounds by the date of the claim it corrects.
766	ALTER TABLE sheet ADD COLUMN policy_date DATE;
