import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { claimsKey } from '../claims/claims';
import { useSheetToday } from '../sheet/sheet';
import { GRADES, peopleKey, usePeople, useShowRetired } from './people';
import { clearSelectedPeople, useSelectedPeople } from './selection';

type BulkGradeResult = { changed: number };

/** The bar that gives every selected person a grade together from a from-date (the sheet's today unless
 *  changed). The server grades each, in list order, as the person form's edit would; the bar then shows how
 *  many were changed. */
function BulkGrade({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const [showRetired] = useShowRetired();
  const chosen = useSelectedPeople(sheetId);
  const ids = people.filter((p) => (showRetired || p.retiredFrom === null) && chosen.has(p.id)).map((p) => p.id);
  const today = useSheetToday(sheetId);
  const [grade, setGrade] = useState('A');
  const [fromEntered, setFrom] = useState<string>();
  const from = fromEntered ?? today;
  const [result, setResult] = useState<BulkGradeResult | null>(null);
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const apply = useMutation({
    mutationFn: (body: { user: string; personIds: number[]; grade: string; from?: string }) =>
      postJson<BulkGradeResult>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-grade`, body),
    onSuccess: async (r) => {
      clearSelectedPeople(sheetId);
      setFrom(undefined);
      setResult(r);
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not grade the selected people.'),
    onSettled: once.done,
  });

  return (
    <p>
      <label>
        Grade selected{' '}
        <select
          data-testid="bulk-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            setError('');
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        from{' '}
        <input
          type="date"
          data-testid="bulk-grade-from"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={apply.isPending}
        onClick={() => {
          setError('');
          setResult(null);
          if (ids.length === 0) {
            setError('Select the people to grade.');
            return;
          }
          if (!once.start()) return;
          apply.mutate({ user, personIds: ids, grade, from: from.trim() === '' ? undefined : from });
        }}
      >
        Grade
      </button>
      {result && (
        <>
          {' '}Changed <span data-testid="bulk-graded">{result.changed}</span>
        </>
      )}
      {error && (
        <span data-testid="person-error" role="alert">
          {' '}{error}
        </span>
      )}
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 11.5, Component: BulkGrade });
# Give the selected people a grade together from a from-date (blank: the sheet's today), in list order. Each is
# graded exactly as the person form's edit would (name and terms kept), with its PERSON_EDITED line and then how the
# sheet's figures moved over it. A refused request (no user, no people, a bad grade or date) writes nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkGrade
  next: grade
grade:
  class: net.officefloor.hq.app.person.BulkGradePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkGrade
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashSet;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user, at least one selected person, a grade of
 *  A, B or C, and a from-date (optional) that is a real yyyy-mm-dd date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        if (request.personIds() == null || request.personIds().isEmpty()) {
            throw new InvalidPersonException("Select the people to grade.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String from = request.from() == null ? "" : request.from().trim();
        LocalDate fromDate = null;
        if (!from.isEmpty()) {
            try {
                fromDate = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        body.set(new BulkGradeInput(request.user().trim(), new LinkedHashSet<>(request.personIds()), grade, fromDate));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkGrade {
    public void respond(@Val BulkGradeResponse result, ObjectResponse<BulkGradeResponse> response) {
        response.send(result);
    }
}

